-- V-003: reservation model. Generated by `prisma migrate dev --create-only`,
-- then hand-edited: everything below the HAND-WRITTEN marker is what Prisma
-- cannot express.

-- A gist index over a plain text column (TableHold.tableId WITH =) needs the
-- btree operator classes. Created before the tables so the whole migration
-- applies top to bottom on a from-scratch database.
CREATE EXTENSION IF NOT EXISTS btree_gist;

-- CreateTable
CREATE TABLE "DiningTable" (
    "id" TEXT NOT NULL,
    "seats" INTEGER NOT NULL,
    "minParty" INTEGER NOT NULL,
    "section" TEXT NOT NULL,

    CONSTRAINT "DiningTable_pkey" PRIMARY KEY ("id")
);

-- CreateTable
CREATE TABLE "Combination" (
    "id" TEXT NOT NULL,
    "seats" INTEGER NOT NULL,
    "minParty" INTEGER NOT NULL,

    CONSTRAINT "Combination_pkey" PRIMARY KEY ("id")
);

-- CreateTable
CREATE TABLE "CombinationMember" (
    "combinationId" TEXT NOT NULL,
    "tableId" TEXT NOT NULL,

    CONSTRAINT "CombinationMember_pkey" PRIMARY KEY ("combinationId","tableId")
);

-- CreateTable
CREATE TABLE "Reservation" (
    "id" UUID NOT NULL,
    "idempotencyKey" TEXT NOT NULL,
    "businessDay" TEXT NOT NULL,
    "startAt" TIMESTAMPTZ(3) NOT NULL,
    "partySize" INTEGER NOT NULL,
    "turnMinutes" INTEGER NOT NULL,
    "tableIds" TEXT[],
    "guestName" TEXT NOT NULL,
    "guestPhone" TEXT NOT NULL,
    "status" TEXT NOT NULL,
    "createdAt" TIMESTAMPTZ(3) NOT NULL,
    "statusChangedAt" TIMESTAMPTZ(3) NOT NULL,

    CONSTRAINT "Reservation_pkey" PRIMARY KEY ("id")
);

-- CreateTable
