ALTER TABLE "CombinationMember" ADD CONSTRAINT "CombinationMember_tableId_fkey" FOREIGN KEY ("tableId") REFERENCES "DiningTable"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

