-- ═══ HAND-WRITTEN ═══════════════════════════════════════════════════════════

-- THE allocation constraint (P0-3). One party per table per instant. Turns
-- vary by party size, so overlapping windows are not EQUAL windows and a
-- UNIQUE index cannot see the collision — `&&` on a half-open range can. A
-- 7:00-8:30 hold and an 8:30-10:00 hold on the same table do not overlap.
-- A combination writes one row per member table, so booking [T4,T5] collides
-- with a deuce already on T5. Violation: SQLSTATE 23P01, which placement
-- (V-005) maps to a clean refusal.
ALTER TABLE "TableHold"
  ADD CONSTRAINT table_hold_no_overlap
  EXCLUDE USING gist ("tableId" WITH =, tstzrange("startAt", "endAt", '[)') WITH &&);

ALTER TABLE "TableHold"
  ADD CONSTRAINT table_hold_window_positive CHECK ("endAt" > "startAt");

ALTER TABLE "Reservation"
  ADD CONSTRAINT reservation_party_positive CHECK ("partySize" > 0),
  ADD CONSTRAINT reservation_turn_positive CHECK ("turnMinutes" > 0),
  ADD CONSTRAINT reservation_has_tables CHECK (cardinality("tableIds") > 0);

-- Same pattern as Countertop's OrderEvent. TRUNCATE is deliberately NOT
-- blocked: it fires TRUNCATE triggers, not row triggers, and it is how the
-- test suite resets between files. Nothing in the application issues one.
CREATE OR REPLACE FUNCTION reservation_event_append_only() RETURNS trigger AS $$
BEGIN
  RAISE EXCEPTION 'ReservationEvent is append-only: % is not permitted (reservation %). Write a revert event instead.',
    TG_OP, OLD."reservationId";
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER reservation_event_append_only
  BEFORE UPDATE OR DELETE ON "ReservationEvent"
  FOR EACH ROW EXECUTE FUNCTION reservation_event_append_only();
